import{_ as o,o as d,c as a,a2 as i}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"官方插件范例","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/examples.md","filePath":"zh-CN/dev-guide/examples.md","lastUpdated":1787586465000}'),r={name:"zh-CN/dev-guide/examples.md"};function c(t,e,l,n,s,h){return d(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="官方插件范例" tabindex="-1">官方插件范例 <a class="header-anchor" href="#官方插件范例" aria-label="Permalink to &quot;官方插件范例&quot;">​</a></h1><p>为了帮助开发者深入理解 <code>Lertaro.PluginSdk</code> 的各模块协同机制，本章节选取了 Lertaro 官方仓库自带的三个典型开源插件进行深度案例剖析。</p><h2 id="_1-coreextensions-——-动作、shell-菜单与快速面板" tabindex="-1">1. CoreExtensions —— 动作、Shell 菜单与快速面板 <a class="header-anchor" href="#_1-coreextensions-——-动作、shell-菜单与快速面板" aria-label="Permalink to &quot;1. CoreExtensions —— 动作、Shell 菜单与快速面板&quot;">​</a></h2><p><code>CoreExtensions</code> 插件是 Lertaro 最核心的功能扩展包，同时实现了 <code>IPlugin</code>、<code>IActionProvider</code>、<code>IConfigurable</code> 以及多个子提供者接口。</p><h3 id="核心实现要点" tabindex="-1">核心实现要点 <a class="header-anchor" href="#核心实现要点" aria-label="Permalink to &quot;核心实现要点&quot;">​</a></h3><ul><li><strong>静态结果动作（<code>IActionProvider.GetActions()</code>）</strong>：注册了 10 个常用的基础文件动作（打开、在资源管理器中定位、复制完整路径、复制/剪切物理文件、打开终端命令行以及提权以管理员身份运行等）。</li><li><strong>原生 Shell 菜单集成（<code>IDynamicActionProvider</code>）</strong>：通过 <code>ShellMenuActionProvider</code> 与 Windows Shell COM 接口交互，将完整的 Windows 右键级联菜单（如“发送到”、7-Zip、VS Code 打开等）无缝渲染至 Lertaro 的 <code>Ctrl+O</code> 动作菜单中。</li><li><strong>模式驱动的配置表单（<code>IConfigurable</code>）</strong>：展示了如何定义包含嵌套分组（<code>Group</code>）、多行字符串列表（<code>StringList</code>）与热键录制（<code>Hotkey</code>）的复杂配置表单，无需手写任何 XAML 即可在设置中心中自动生成。</li><li><strong>多样化的快速面板标签（<code>IQuickPanelTabProvider</code>）</strong>： <ul><li><code>FavoritesTabProvider</code> / <code>HistoryTabProvider</code>：直接将内存中的结构化列表包装为结果集，属于零 I/O 极简实现。</li><li><code>WindowsRecentTabProvider</code>：在后台任务中遍历系统 <code>Recent</code> 目录并通过 COM 解析快捷方式目标，预先截断并填充 <code>Metadata.Modified</code> 时间戳以实现“最新在前”。</li><li><code>LastDirectoryTabProvider</code> / <code>RecentFilesTabProvider</code>：直接调用宿主公开的 <a href="./sdk/services.html"><code>ExplorerPathService</code></a> 与 <code>RecentFilesService</code> 查询宿主已有状态。</li></ul></li></ul><h2 id="_2-pinyinalias-——-非-ascii-别名转写引擎" tabindex="-1">2. PinyinAlias —— 非 ASCII 别名转写引擎 <a class="header-anchor" href="#_2-pinyinalias-——-非-ascii-别名转写引擎" aria-label="Permalink to &quot;2. PinyinAlias —— 非 ASCII 别名转写引擎&quot;">​</a></h2><p><code>PinyinAlias</code> 插件专门为中文文件名提供拼音全拼与首字母缩写检索支持，同时实现了 <code>IAliasProvider</code> 与 <code>ITranslationProvider</code> 两个接口。</p><h3 id="核心实现要点-1" tabindex="-1">核心实现要点 <a class="header-anchor" href="#核心实现要点-1" aria-label="Permalink to &quot;核心实现要点&quot;">​</a></h3><ul><li><strong>输入/输出字母表边界（<code>InputRanges</code> / <code>OutputRanges</code>）</strong>：声明输入源字符范围为 CJK 表意文字区块，输出字符范围为小写 <code>a</code>–<code>z</code>。宿主利用该边界智能将“大cj”等混合查询切分为字面匹配与拼音别名匹配。</li><li><strong>快速预检过滤（<code>CanHandle(text)</code>）</strong>：在生成别名前先扫描文本中是否存在中文字符，对于纯英文字符串直接返回 <code>false</code>，完全跳过后续开销。</li><li><strong>多音字组合与别名构建（<code>GetAliases(text)</code>）</strong>：先构建字符级音节表，对于含多音字的文件名（如“重”、“长”），自动生成各常见读音组合并使用 <code>|</code> 管道符连接（上限 32 种组合以防爆炸），供搜索引擎作为候选集并行匹配。</li><li><strong>内嵌多语言与线程安全缓存</strong>：通过 <code>ITranslationProvider</code> 提供插件显示名称与描述的多语言本地化，并在内部使用带 <code>lock</code> 保护的字典缓存解析后的 JSON 翻译，避免每次查询重复解析。</li></ul><h2 id="_3-flowlauncherbridge-——-跨生态桥接与隔离运行时" tabindex="-1">3. FlowLauncherBridge —— 跨生态桥接与隔离运行时 <a class="header-anchor" href="#_3-flowlauncherbridge-——-跨生态桥接与隔离运行时" aria-label="Permalink to &quot;3. FlowLauncherBridge —— 跨生态桥接与隔离运行时&quot;">​</a></h2><p><code>FlowLauncherBridge</code> 插件展示了如何构建一个大型复合型桥接系统，将外部开源社区生态无缝吸纳进 Lertaro 体系。</p><h3 id="核心实现要点-2" tabindex="-1">核心实现要点 <a class="header-anchor" href="#核心实现要点-2" aria-label="Permalink to &quot;核心实现要点&quot;">​</a></h3><ul><li><strong>多语言跨进程桥接</strong>：兼容 C# (.NET)、Python 3.12、Node.js v20 LTS 及独立 <code>.exe</code> 形式的 Flow Launcher 插件。</li><li><strong>纯净自包含环境</strong>：在用户数据目录中自动隔离部署 Python / Node.js 运行时，并通过命名管道与子进程进行 JSON-RPC 通信。</li><li><strong>动态配置与富文本预览</strong>：解析外部插件的 <code>SettingsTemplate.yaml</code>/<code>.json</code> 并动态映射为 <code>PluginConfigSchema</code>；在 QuickLook 预览面板中利用 WebView2 渲染外部插件返回的富文本卡片（如词典释义、实时天气等）。</li></ul>',14)])])}const P=o(r,[["render",c]]);export{g as __pageData,P as default};
